/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, char separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {



    @Test
    public void testJoin_NoOfItemsIsZero() {
        Object[] array = {"a", "b", "c"};
        // startIndex == endIndex results in noOfItems = 0
        assertEquals("Should return empty string when startIndex equals endIndex", 
            "", StringUtils.join(array, ',', 1, 1));

        // startIndex > endIndex results in negative noOfItems
        assertEquals("Should return empty string when startIndex is greater than endIndex", 
            "", StringUtils.join(array, ',', 2, 1));
    }










}

