import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, char separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen1Test {









    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"A", null, "C", null};
        // The code says: if (array[i] != null) { buf.append(array[i]); }
        // This means nulls are skipped but the separator is still appended if i > startIndex
        assertEquals("Should skip null elements but keep separators", 
            "A,,C,", StringUtils.join(array, ',', 0, 4));

        // Test null at start
        Object[] array2 = {null, "B", "C"};
        assertEquals("Should handle null at start", 
            "B,C", StringUtils.join(array2, ',', 0, 3));
    }




}

